 * Evaluate a feature flag with the following priority:
 * 1. Local dev override (VITE_FORCE_FLAG_*)
 * 2. Global dev override (VITE_FORCE_ALL_FLAGS)
 * 3. PostHog JS client-side value (supports toolbar overrides, device bucketing)
 * 4. Server-side flags from /auth/me (instant for authenticated users)
 *
 * Returns `undefined` while flags are still loading for unauthenticated users
 * (PostHog JS hasn't resolved yet and there are no server-side flags).
 * Callers should handle undefined as a loading state.
 */
export function useManagedFeatureFlag(key: FeatureFlagKey): boolean | undefined {
  const localOverride = getLocalFeatureFlagOverride(key)
  const globalOverride = getGlobalFeatureFlagOverride()
  const { user } = useAuth()
  // PostHog client-side value — reflects toolbar overrides
  const posthogValue = useFeatureFlagEnabled(key)

  if (localOverride !== undefined) {
    return localOverride
  }

  if (globalOverride !== undefined) {
    return globalOverride
  }

  if (posthogValue !== undefined) {
    return posthogValue === true
  }

  // For authenticated users, server-side flags from /auth/me provide instant
  // values — but only when the flag is explicitly present. The server evaluates
  // flags with `onlyEvaluateLocally: true`, which can't resolve property-based
  // targeting rules (e.g. `github_login = evisdren`). When the flag is absent
  // from the server response, return undefined (loading) so callers wait for the
  // PostHog JS client to resolve rather than prematurely treating it as false.
  if (user) {
    const serverValue = user.feature_flags?.[key]
    if (serverValue !== undefined) {
      return serverValue === true
    }
    // Flag not in server response — can't evaluate locally. Wait for PostHog JS.
    return undefined
  }

  return undefined
}

