            if r.get("best"): wins[lm[r["best"]]] += 1 / len(judge_names)
        d_ov = st.mean(ov["deepseek-v4-flash"]); h_ov = st.mean(ov["haiku-4-5"])
        h2h["deepseek-v4-flash" if d_ov > h_ov else "haiku-4-5" if h_ov > d_ov else "tie"] += 1
