    print(f"{'model':20}{'label':>8}{'summ':>8}{'struct':>8}{'overall':>9}{'mrank':>8}{'#best':>7}")
    for m in sorted(MODELS, key=lambda m: st.mean(per[m]['overall']) if per[m]['overall'] else 0, reverse=True):
        row = f"{m:20}"
        for d in DIMS:
            row += f"{(st.mean(per[m][d]) if per[m][d] else 0):8.2f}" if d != "overall" else f"{(st.mean(per[m][d]) if per[m][d] else 0):9.2f}"
        mr = st.mean(ranks[m]) if ranks[m] else 0
        row += f"{mr:8.2f}{wins[m]:7.1f}"
        print(row)
    print(f"DeepSeek vs Haiku head-to-head (by mean overall/item): "
          f"DeepSeek {h2h['deepseek-v4-flash']}  Haiku {h2h['haiku-4-5']}  tie {h2h['tie']}")
    return per, h2h

