242	// CalculateModelUsage attributes per-message token usage to the model that
243	// produced it (message.model), over the MAIN transcript only. The
244	// ModelUsageCalculator signature carries no subagentsDir, so unlike
245	// CalculateTotalTokenUsage this covers only the main-agent transcript; the
246	// dispatcher's remainder bucket attributes any subagent shortfall under the
247	// session model. It reuses the flat token loop's dedup semantics — one row per
248	// message.id, keeping the highest output_tokens (final streaming state) — and
249	// buckets each kept row by that row's model. Buckets are returned sorted by
250	// model for deterministic output and sum to the flat CalculateTokenUsage total
251	// over the same main-transcript slice. Cost fields are left nil; the framework
252	// prices each bucket.
253	func (c *ClaudeCodeAgent) CalculateModelUsage(transcriptData []byte, fromOffset int) ([]agent.ModelUsage, error) {
254		if len(transcriptData) == 0 {
255			return nil, nil
256		}
257	
258		sliced := transcript.SliceFromLine(transcriptData, fromOffset)
259		parsed, err := transcript.ParseFromBytes(sliced)
260		if err != nil {
261			return nil, fmt.Errorf("failed to parse transcript: %w", err)
262		}
263	
264		// Deduplicate by message.id, keeping the highest-output row; the model rides
265		// the kept row so attribution matches the flat token loop exactly.
266		rowByID := make(map[string]modelUsageRow)
267		for _, line := range parsed {
268			if line.Type != envelopeTypeAssistant {
269				continue
270			}
271			var msg messageWithUsage
272			if err := json.Unmarshal(line.Message, &msg); err != nil {
273				continue
274			}
275			if msg.ID == "" {
276				continue
277			}
278			existing, exists := rowByID[msg.ID]
279			if !exists || msg.Usage.OutputTokens > existing.usage.OutputTokens {
280				rowByID[msg.ID] = modelUsageRow{model: msg.Model, usage: msg.Usage}
281			}
