#!/usr/bin/env python3
"""Op decomposition for any (eg-arm, baseline-arm) pair: pre-edit vs post-edit tail.

Splits each session at its LAST edit. Before = locate + edit. After = verify/build tail.
Also counts environment/toolchain probes in the tail -- the signature of an agent chasing a
VERIFY command that cannot run in the checkout.

Usage: decomp.py <egTag> <egArm> <baseTag>
"""
from __future__ import annotations
import json, glob, os, re, sys, math

AS = "/Users/suhaan/graphmark-bench/agentic-swebench"
PROJ = os.path.expanduser("~/.claude/projects")
IDX = {os.path.basename(p)[:-6]: p for p in glob.glob(f"{PROJ}/*/*.jsonl")}
EXPLORE = re.compile(r'\b(grep|rg|find|sed -n|cat |head |tail |ls )')
ENVPROBE = re.compile(r'java_home|JAVA_HOME|\bwhich\b|ls vendor|find [^|]*\.jar|pom\.xml|'
                      r'node_modules|\bnvm\b|pyenv|rustup|\.m2\b|gradlew|bundle exec|gem list|--version', re.I)


def profile(tag, arm, iid):
    f = f"{AS}/results/{tag}/{arm}/{iid}/cc_out.json"
    if not os.path.exists(f):
        return None
    try:
        j = json.load(open(f))
    except Exception:
        return None
    pd = f"{AS}/results/{tag}/{arm}/{iid}/patch.diff"
    if (j.get("total_cost_usd", 0) or 0) <= 0 or not os.path.exists(pd) or os.path.getsize(pd) == 0:
        return None
    p = IDX.get(j.get("session_id") or "")
    if not p:
        return None
    calls = []
    for line in open(p, errors="ignore"):
        try:
            o = json.loads(line)
        except Exception:
            continue
        c = (o.get("message") or {}).get("content")
        if not isinstance(c, list):
            continue
        for b in c:
            if isinstance(b, dict) and b.get("type") == "tool_use":
                calls.append((b.get("name"), (b.get("input") or {}).get("command", "") or ""))
    le = max((i for i, (n, _) in enumerate(calls) if n in ("Edit", "MultiEdit", "Write")), default=-1)
    pre, post = calls[:le + 1], calls[le + 1:]
    u = j.get("usage", {}) or {}
    return {
        "pre": len(pre), "post": len(post), "total": len(calls),
        "preEx": sum(1 for n, c in pre if n == "Bash" and "eg-q" not in c and EXPLORE.search(c)),
        "postEx": sum(1 for n, c in post if n == "Bash" and "eg-q" not in c and EXPLORE.search(c)),
        "env": sum(1 for n, c in post if n == "Bash" and ENVPROBE.search(c)),
        "edits": sum(1 for n, _ in calls if n in ("Edit", "MultiEdit", "Write")),
        "tok": sum(u.get(k, 0) for k in ("input_tokens", "output_tokens",
                                         "cache_creation_input_tokens", "cache_read_input_tokens")),
    }


def main():
    egtag, egarm, basetag = sys.argv[1], sys.argv[2], sys.argv[3]
    d = f"{AS}/results/{egtag}/{egarm}"
    if not os.path.isdir(d):
        print(f"  {egtag}/{egarm}: missing"); return
    E, B, pos = [], [], []
    for iid in sorted(os.listdir(d)):
        e = profile(egtag, egarm, iid)
        b = profile(basetag, "baseline", iid)
        if not e or not b:
            continue
        E.append(e); B.append(b)
        if e["post"] > b["post"]:
            pos.append((iid, e["post"] - b["post"], e["env"]))
    n = len(E)
    if n < 5:
        print(f"  {egtag} vs {basetag}: only {n} pairs"); return
    m = lambda L, k: sum(x[k] for x in L) / len(L)
    tk = [math.log(e["tok"] / b["tok"]) for e, b in zip(E, B) if e["tok"] > 0 and b["tok"] > 0]
    tokd = (math.exp(sum(tk) / len(tk)) - 1) * 100 if tk else float("nan")
    print(f"\n=== {egtag}/{egarm} vs {basetag}/baseline   n={n} ===")
    print(f"  tokens (geomean)      : {tokd:+6.1f}%")
    print(f"  PRE-edit  ops         : eg {m(E,'pre'):5.1f}  base {m(B,'pre'):5.1f}   delta {m(E,'pre')-m(B,'pre'):+5.1f}")
    print(f"  POST-edit ops         : eg {m(E,'post'):5.1f}  base {m(B,'post'):5.1f}   delta {m(E,'post')-m(B,'post'):+5.1f}")
    print(f"  TOTAL ops             : eg {m(E,'total'):5.1f}  base {m(B,'total'):5.1f}   delta {m(E,'total')-m(B,'total'):+5.1f}")
    tot = m(E, 'total') - m(B, 'total')
    if tot:
        print(f"  share of delta from tail: {(m(E,'post')-m(B,'post'))/tot*100:5.0f}%")
    print(f"  eg env-probes in tail  : {m(E,'env'):5.2f}/task   base {m(B,'env'):5.2f}/task")
    if pos:
        tp = sum(x[1] for x in pos); te = sum(x[2] for x in pos)
        print(f"  longer-tail instances : {len(pos)}  total +{tp} calls, env-probes {te} ({te/tp*100:.0f}%)")
        for iid, dp, en in sorted(pos, key=lambda x: -x[1])[:4]:
            print(f"      {iid[:34]:34} +{dp:<3} env={en}")


if __name__ == "__main__":
    main()

